1	import * as THREE from 'three';
2	import { generateCity } from './City.js';
3	import { Sun } from './Sun.js';
4	import { Player } from './Player.js';
5	import { Minimap } from './Minimap.js';
6	
7	const GOAL_RADIUS = 3;
8	const UP = new THREE.Vector3(0, 1, 0);
9	
10	/* 마우스 오토룩 — 화면 중앙에서 벗어난 만큼 시점이 그 방향으로 계속 회전한다 */
11	const LOOK_DEADZONE = 0.08;
12	const YAW_MAX_SPEED = 1.7;   // rad/s
13	const PITCH_MAX_SPEED = 1.1; // rad/s
14	const PITCH_MIN = 0.15;
15	const PITCH_MAX = 1.15;
16	const DIST_MIN = 4;
17	const DIST_MAX = 20;
18	const ZOOM_SPEED = 0.0016;
19	
20	/* ==========================================================================
21	 *  그림자 도시 — 태양을 피해 그늘만 밟고 목적지에 도달하는 3D 생존 게임.
22	 * ========================================================================== */
23	export class Game {
24	  constructor() {
25	    this.dom = {
26	      container: document.getElementById('game'),
27	      loading: document.getElementById('loading'),
28	      burnVignette: document.getElementById('burnVignette'),
29	      hpFill: document.getElementById('hpFill'),
30	      hpNum: document.getElementById('hpNum'),
31	      statusTag: document.getElementById('statusTag'),
32	      dayFill: document.getElementById('dayFill'),
33	      dayTime: document.getElementById('dayTime'),
34	      goalDist: document.getElementById('goalDist'),
35	      minimapCanvas: document.getElementById('minimap'),
36	      endScreen: document.getElementById('endScreen'),
37	      endTitle: document.getElementById('endTitle'),
38	      endSub: document.getElementById('endSub'),
39	      restartBtn: document.getElementById('restartBtn'),
40	    };
41	
42	    this.state = 'playing'; // 'playing' | 'won' | 'lost'
43	    this.keys = new Set();
44	    this.clock = new THREE.Clock();
45	    this.raycaster = new THREE.Raycaster();
46	
47	    this.initScene();
48	    this.initCity();
49	    this.initCamera();
50	    this.initInput();
51	
52	    this.dom.loading.style.display = 'none';
53	    if (import.meta.env.DEV) window.__game = this;
54	    requestAnimationFrame(() => this.loop());
55	  }
56	
57	  initScene() {
58	    this.scene = new THREE.Scene();
59	    this.fog = new THREE.Fog(0x141824, 40, 210);
60	    this.scene.fog = this.fog;
61	
62	    this.renderer = new THREE.WebGLRenderer({ antialias: true });
63	    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
64	    this.renderer.setSize(window.innerWidth, window.innerHeight);
65	    this.renderer.shadowMap.enabled = true;
66	    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
67	    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
68	    this.dom.container.appendChild(this.renderer.domElement);
69	
70	    window.addEventListener('resize', () => this.onResize());
71	  }
72	
73	  initCity() {
74	    this.city = generateCity(this.scene);
75	    this.fog.far = this.city.extent * 1.1;
76	    this.sun = new Sun(this.scene, this.city.extent);
77	    this.player = new Player(this.scene, this.city.spawn);
78	    this.buildGoalBeacon();
79	    this.minimap = new Minimap(this.dom.minimapCanvas, this.city);
80	  }
81	
82	  buildGoalBeacon() {
83	    const g = this.city.goal;
84	    const group = new THREE.Group();
85	    group.position.set(g.x, 0, g.z);
86	
87	    const pillar = new THREE.Mesh(
88	      new THREE.CylinderGeometry(0.3, 0.3, 6, 12),
89	      new THREE.MeshStandardMaterial({ color: 0xd9a441, emissive: 0xd9a441, emissiveIntensity: 0.8, roughness: 0.4 }),
90	    );
91	    pillar.position.y = 3;
92	    group.add(pillar);
93	
94	    const ring = new THREE.Mesh(
95	      new THREE.TorusGeometry(1.4, 0.08, 8, 32),
96	      new THREE.MeshStandardMaterial({ color: 0xffd280, emissive: 0xffd280, emissiveIntensity: 1 }),
97	    );
98	    ring.rotation.x = Math.PI / 2;
99	    ring.position.y = 0.4;
100	    group.add(ring);
101	    this.goalRing = ring;
102	
103	    const light = new THREE.PointLight(0xffcf6b, 2.2, 18, 2);
104	    light.position.y = 3;
105	    group.add(light);
106	
107	    this.scene.add(group);
108	  }
109	
110	  initCamera() {
111	    this.camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 400);
112	    const s = this.city.spawn;
113	
114	    // 스폰 지점에서 도시 중심(목적지 방향)을 바라보도록 초기 시점을 잡는다
115	    const intoCity = new THREE.Vector3(-s.x, 0, -s.z).normalize();
116	    this.camYaw = Math.atan2(intoCity.x, intoCity.z);
117	    this.camPitch = 0.58;
118	    this.camDist = 12;
119	    this.camTarget = new THREE.Vector3(s.x, 1.2, s.z);
120	
121	    this.updateCameraTransform();
122	  }
123	
124	  initInput() {
125	    window.addEventListener('keydown', (e) => {
126	      this.keys.add(e.key.toLowerCase());
127	      if (e.key.toLowerCase() === 'r' && this.state !== 'playing') this.restart();
128	    });
129	    window.addEventListener('keyup', (e) => this.keys.delete(e.key.toLowerCase()));
130	    this.dom.restartBtn.addEventListener('click', () => this.restart());
131	
132	    // 마우스 오토룩 — 클릭/드래그 없이 커서 위치만으로 시점이 회전한다
133	    this.mouseN = { x: 0, y: 0 };
134	    window.addEventListener('mousemove', (e) => {
135	      this.mouseN.x = (e.clientX / window.innerWidth) * 2 - 1;
136	      this.mouseN.y = (e.clientY / window.innerHeight) * 2 - 1;
137	    });
138	    window.addEventListener('mouseleave', () => { this.mouseN.x = 0; this.mouseN.y = 0; });
139	
140	    this.renderer.domElement.addEventListener('wheel', (e) => {
141	      e.preventDefault();
142	      this.camDist = THREE.MathUtils.clamp(this.camDist + e.deltaY * ZOOM_SPEED * this.camDist, DIST_MIN, DIST_MAX);
143	    }, { passive: false });
144	    this.renderer.domElement.addEventListener('contextmenu', (e) => e.preventDefault());
145	  }
146	
147	  /** 화면 중앙에서 벗어난 마우스 위치만큼 시점을 계속 돌린다 (데드존 적용) */
148	  updateLook(dt) {
149	    const applyDeadzone = (v) => {
150	      const a = Math.abs(v);
151	      if (a < LOOK_DEADZONE) return 0;
152	      const eased = (a - LOOK_DEADZONE) / (1 - LOOK_DEADZONE);
153	      return Math.sign(v) * eased * eased;
154	    };
155	
156	    const yawInput = applyDeadzone(this.mouseN.x);
157	    const pitchInput = applyDeadzone(this.mouseN.y);
158	
159	    this.camYaw += yawInput * YAW_MAX_SPEED * dt;
160	    this.camPitch = THREE.MathUtils.clamp(
161	      this.camPitch - pitchInput * PITCH_MAX_SPEED * dt,
162	      PITCH_MIN, PITCH_MAX,
163	    );
164	  }
165	
166	  updateCameraTransform() {
167	    const horiz = this.camDist * Math.cos(this.camPitch);
168	    const height = this.camDist * Math.sin(this.camPitch);
169	    this.camera.position.set(
170	      this.camTarget.x - Math.sin(this.camYaw) * horiz,
171	      this.camTarget.y + height,
172	      this.camTarget.z - Math.cos(this.camYaw) * horiz,
173	    );
174	    this.camera.lookAt(this.camTarget);
175	  }
176	
177	  restart() { window.location.reload(); }
178	
179	  onResize() {
180	    this.camera.aspect = window.innerWidth / window.innerHeight;
181	    this.camera.updateProjectionMatrix();
182	    this.renderer.setSize(window.innerWidth, window.innerHeight);
183	  }
184	
185	  /** 카메라 시점 기준 WASD 이동 벡터 (XZ 평면) */
186	  computeMoveDir() {
187	    const forward = new THREE.Vector3(Math.sin(this.camYaw), 0, Math.cos(this.camYaw));
188	    const right = new THREE.Vector3().crossVectors(forward, UP).normalize();
189	
190	    const dir = new THREE.Vector3();
191	    const k = this.keys;
192	    if (k.has('w') || k.has('arrowup')) dir.add(forward);
193	    if (k.has('s') || k.has('arrowdown')) dir.sub(forward);
194	    if (k.has('d') || k.has('arrowright')) dir.add(right);
