  });
  window.addEventListener('keyup', (e) => this.keys.delete(e.key.toLowerCase()));
  this.dom.restartBtn.addEventListener('click', () => this.restart());

  // 마우스 오토룩 — 클릭/드래그 없이 커서 위치만으로 시점이 회전한다
  this.mouseN = { x: 0, y: 0 };
  window.addEventListener('mousemove', (e) => {
    this.mouseN.x = (e.clientX / window.innerWidth) * 2 - 1;
    this.mouseN.y = (e.clientY / window.innerHeight) * 2 - 1;
  });
  window.addEventListener('mouseleave', () => { this.mouseN.x = 0; this.mouseN.y = 0; });

  this.renderer.domElement.addEventListener('wheel', (e) => {
    e.preventDefault();
    this.camDist = THREE.MathUtils.clamp(this.camDist + e.deltaY * ZOOM_SPEED * this.camDist, DIST_MIN, DIST_MAX);
  }, { passive: false });
  this.renderer.domElement.addEventListener('contextmenu', (e) => e.preventDefault());
}

/** 화면 중앙에서 벗어난 마우스 위치만큼 시점을 계속 돌린다 (데드존 적용) */
updateLook(dt) {
  const applyDeadzone = (v) => {
    const a = Math.abs(v);
    if (a < LOOK_DEADZONE) return 0;
    const eased = (a - LOOK_DEADZONE) / (1 - LOOK_DEADZONE);
    return Math.sign(v) * eased * eased;
  };

  const yawInput = applyDeadzone(this.mouseN.x);
  const pitchInput = applyDeadzone(this.mouseN.y);

  this.camYaw += yawInput * YAW_MAX_SPEED * dt;
  this.camPitch = THREE.MathUtils.clamp(
    this.camPitch - pitchInput * PITCH_MAX_SPEED * dt,
    PITCH_MIN, PITCH_MAX,
  );
}

